// nova.ts: Nova's entry in the registry of Jira triggers.
QUERIES.set("nova", {
  name: "nova", agent: "nova", every: "1 minute",
  jql: "project = RH AND assignee = currentUser() AND statusCategory != Done",
  toStart: async (issue) => {
    const requester = await requesterOf(issue.key); // who assigned the ticket to Nova
    if (!requester) return undefined;               // never start a run without a person behind it
    return [ticketToPr, { key: issue.key, requester }];
  },
});

// schedules.ts: the activity behind every tick of poll-jira-<name>.
export const startMatches = async (name: string): Promise<number> => {
  const q = QUERIES.get(name)!;
  const issues = await jira.searchAll(q.jql);
  for (const issue of issues) {
    const start = await q.toStart(issue);
    if (start) await startRun(await temporalClient(), q.agent, issue.key, ...start); // nova:RH-1234 joins the open run
  }
  return issues.length;
};

const DAY = 24 * 60 * 60 * 1000;
const WAITS: Record<Wait, [remindAfter: number, handBackAfter: number]> = {
  plan: [1 * DAY, 3 * DAY],
  question: [1 * DAY, 2 * DAY],
  review: [2 * DAY, 14 * DAY],
};

/** True when the person acted; false when the run was stopped or the ticket was handed back. */
export const waitForPerson = async (wf: RunState, what: Wait, done: () => boolean, t: Handoff): Promise<boolean> => {
  const [remind, handBackAt] = scaled(WAITS[what], t.drill);
  const over = () => done() || wf.stopped;
  if (await condition(over, remind)) return !wf.stopped;
  await peopleApis.notify(t, REMINDERS[what](t.requester));
  if (await condition(over, handBackAt - remind)) return !wf.stopped;
  await peopleApis.handBack(t, PARK_NOTES[what]);
  return false;
};

