// Stand-ins for Jira, Slack and the sandbox. fake-jira.json plays Jira; every line is printed in the worker terminal.
import { readFile, writeFile } from 'node:fs/promises';
import { sleep } from '@temporalio/activity';
import { connect } from './connect.mjs';
import { startRun } from './start-run.mjs';

const now = () => new Date().toTimeString().slice(0, 8);
const readJira = async () => JSON.parse(await readFile('fake-jira.json', 'utf8'));
let client;
let vms = 0;

// The registry of Jira triggers. Nova's query is "assigned to Nova"; toStart says what to start for one match.
const QUERIES = {
  nova: { agent: 'nova', jql: 'assignee = Nova', match: (issue) => issue.assignee === 'Nova',
    toStart: (key, issue) => ['ticketToPr', { key, requester: issue.requester }] },
};

// One poll of one query: start or join one run per matching ticket.
export const startMatches = async (name) => {
  const q = QUERIES[name];
  const jira = await readJira();
  client ??= await connect();
  const keys = Object.keys(jira).filter((key) => q.match(jira[key]));
  for (const key of keys) {
    const [wf, handoff] = q.toStart(key, jira[key]);
    await startRun(client, q.agent, key, wf, handoff); // nova:RH-1234 again and again: it joins the open run
  }
  return keys.length;
};

export const planInSandbox = async (t) => {
  const vm = `i-0${String(++vms).padStart(3, '0')}`;
  console.log(`${now()}  ${t.key}  claimed a lite VM ${vm} and wrote a plan`);
  await sleep(2000);
  console.log(`${now()}  ${t.key}  posted the plan in Slack and Jira, released ${vm}`);
  return 'plan v1';
};

export const notify = async (t, text) => console.log(`${now()}  ${t.key}  Slack thread: "${text}"`);

// Every way a run ends gives the ticket back to a person: say why, and make the requester the assignee again.
export const handBack = async (t, why) => {
  const jira = await readJira();
  jira[t.key].assignee = t.requester;
  await writeFile('fake-jira.json', JSON.stringify(jira) + '\n');
  console.log(`${now()}  ${t.key}  "${why}"  assignee: ${jira[t.key].assignee}`);
};
EOF

