// Nova's run for one ticket and the Jira poll, cut down to what this lab needs.
import { condition, defineQuery, defineSignal, proxyActivities, setHandler } from '@temporalio/workflow';

const act = proxyActivities({ startToCloseTimeout: '7 days', heartbeatTimeout: '2 minutes' });
const people = proxyActivities({ startToCloseTimeout: '1 minute' });

export const decidePlan = defineSignal('decidePlan');
export const stop = defineSignal('stop');
export const statusQuery = defineQuery('status');

// A drill ticket: one "day" lasts 10 seconds, so a 3-day wait takes 30 seconds.
const DAY = 10_000;
const WAITS = { plan: [1 * DAY, 3 * DAY], question: [1 * DAY, 2 * DAY], review: [2 * DAY, 14 * DAY] };
const REMINDERS = { plan: (who) => `@${who}, the plan is still waiting for your decision.` };
const PARK_NOTES = { plan: 'Nobody decided on the plan in 3 days, so I am handing the ticket back.' };

// Build it: wait until done() is true, a Stop arrives, or the park time passes.
// Remind once at WAITS[what][0], park at WAITS[what][1]. True when the person acted, false otherwise.
// For now it waits forever: no reminder, no parking, and Stop is ignored.
export const waitForPerson = async (run, what, done, t) => {
  await condition(done);
  return true;
};

export async function ticketToPr(t) {
  const run = { status: 'Checking', stoppedBy: undefined };
  let decision;
  setHandler(statusQuery, () => run.status);
  setHandler(decidePlan, (d) => { decision = d; });
  setHandler(stop, (by) => { run.stoppedBy = by; });

  run.status = 'Planning';
  await act.planInSandbox(t);
  run.status = 'Awaiting approval';
  if (!(await waitForPerson(run, 'plan', () => decision !== undefined, t))) {
    if (!run.stoppedBy) return (run.status = 'Parked'); // waitForPerson already handed the ticket back
    await people.handBack(t, `Stopped by ${run.stoppedBy}. The branch and notes are kept.`);
    return (run.status = `Stopped by ${run.stoppedBy}`);
  }
  run.status = 'Working';
  await people.handBack(t, 'Draft PR #2512 is ready for review.'); // the build is cut from this lab
  return (run.status = 'PR open: draft PR #2512');
}

// What the schedule poll-jira-nova starts every few seconds: one poll of one query.
export async function pollJira(name) {
  return people.startMatches(name);
}
EOF

