cat > ensure-schedules.mjs <<'EOF'
// What the orchestrator does when its worker starts: create each poll schedule, or update it if it exists.
import { ScheduleAlreadyRunning, ScheduleOverlapPolicy } from '@temporalio/client';
import { connect } from './connect.mjs';

const QUERIES = [{ name: 'nova', every: '5 seconds' }]; // the real Nova poll runs every minute

const client = await connect();
for (const q of QUERIES) {
  const scheduleId = `poll-jira-${q.name}`;
  const schedule = {
    spec: { intervals: [{ every: q.every }] },
    action: { type: 'startWorkflow', workflowType: 'pollJira', args: [q.name], workflowId: scheduleId, taskQueue: 'ai-agents-orchestrator' },
    policies: { overlap: ScheduleOverlapPolicy.SKIP, catchupWindow: q.every },
  };
  await client.schedule.create({ scheduleId, ...schedule }).then(
    () => console.log(`created ${scheduleId}`),
    async (err) => {
      if (!(err instanceof ScheduleAlreadyRunning)) throw err;
      await client.schedule.getHandle(scheduleId).update((prev) => ({ ...prev, ...schedule }));
      console.log(`updated ${scheduleId}`);
    });
}
await client.connection.close();
EOF

