  const over = () => done() || run.stoppedBy !== undefined; // Stop always ends the wait
  if (await condition(over, remind)) return !run.stoppedBy;
  await people.notify(t, REMINDERS[what](t.requester));
  if (await condition(over, park - remind)) return !run.stoppedBy;
  await people.handBack(t, PARK_NOTES[what]);
  return false;
};
